21	/// `flutter_secure_storage` + `get_it` integration spike this story proves
22	/// before anything else is built on top of it.
23	Future<void> setupCoreDependencies() async {
24	  await dotenv.load(fileName: '.env');
25	
26	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
27	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
