29	  sl.registerLazySingleton<FlutterSecureStorage>(
30	    () => const FlutterSecureStorage(),
31	  );
32	
33	  sl.registerLazySingleton<AccessTokenProvider>(
34	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
35	  );
36	
37	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
38	
39	  sl.registerLazySingleton<Dio>(() {
40	    final dio = Dio(
41	      BaseOptions(
42	        // Design note (docs/input is silent on exact numbers): a stalled
43	        // connection must still fail instead of hanging indefinitely.
44	        connectTimeout: const Duration(seconds: 10),
45	        receiveTimeout: const Duration(seconds: 30),
46	        sendTimeout: const Duration(seconds: 30),
47	      ),
48	    );
49	    dio.interceptors.add(
50	      HeaderInterceptor(
51	        anonKey: supabaseAnonKey,
52	        accessTokenProvider: sl<AccessTokenProvider>(),
53	      ),
54	    );
55	    dio.interceptors.add(RetryInterceptor(dio));
56	    return dio;
57	  });
58	
59	  sl.registerLazySingleton<ApiClient>(
60	    () => ApiClient(dio: sl<Dio>(), urlBuilder: sl<UrlBuilder>()),
